function splitLabel(text){const parts=String(text||'').split(/\s+\/\s+/).map(x=>x.trim()).filter(Boolean);const zh=parts.filter(x=>/[㐀-鿿]/.test(x)).join(' / ');const en=parts.filter(x=>!/[㐀-鿿]/.test(x)).join(' / ');return{zh,en};}
function langValue(map,lang){return map?.[lang]||map?.en||'';}
function text(zh,en,lang=core.language()){
 lang=String(lang||'bilingual');if(lang==='zh')return zh||en;if(lang==='en')return en||zh;if(lang==='bilingual')return zh&&en?`${zh} / ${en}`:(zh||en);
 const exact=phrases.get(en)||phraseNorm.get(norm(en));if(exact?.[lang])return exact[lang];
 const aliasKey=Object.keys(alias).find(k=>norm(k)===norm(en));const key=(aliasKey?alias[aliasKey]:null)||core.findKey?.(zh,en);if(key){const v=core.raw?.(key)?.[lang];if(v)return v;}
 const roleMatch=String(en||'').match(/^(Seller|Buyer|Customer|Consignee|Notify(?: Party)?|Exporter|Shipper)\s+(Contact|Phone|Email|Address|Tax ID|Country|Website)$/i);
 if(roleMatch){let rawRole=roleMatch[1];if(/^Notify$/i.test(rawRole))rawRole='Notify Party';const roleName=Object.keys(roles).find(x=>x.toLowerCase()===rawRole.toLowerCase()),attrName=Object.keys(attrs).find(x=>x.toLowerCase()===roleMatch[2].toLowerCase());const rv=roleName?((phrases.get(roleName)||phraseNorm.get(norm(roleName)))?.[lang]||core.raw?.(roles[roleName].key)?.[lang]):'';const av=attrName?core.raw?.(attrs[attrName])?.[lang]:'';if(rv&&av)return `${rv} · ${av}`;}
 return en||zh;
}
function phraseByAny(raw){const target=norm(raw);if(!target)return null;const direct=phrases.get(String(raw||'').trim())||phraseNorm.get(target);if(direct)return direct;for(const map of phrases.values()){if(Object.values(map).some(value=>norm(value)===target))return map;}return null;}
function localizeLabel(label,lang=core.language()){const p=splitLabel(label);if(!p.zh||!p.en){const raw=String(label||'').trim();const map=phraseByAny(raw);return map?.[lang]||raw;}return text(p.zh,p.en,lang);}
